const http = require('http');
const { execSync } = require('child_process');
const AWS = require('aws-sdk');

// Global state for signal handling
let isShuttingDown = false;
let activeConnections = new Map();
let credentialCache = null;

// Signal handler for graceful shutdown in Lambda extensions
process.on('SIGTERM', () => {
  isShuttingDown = true;
  // Flush metrics before shutdown
  flushMetricsToEndpoint();
});

process.on('SIGUSR2', () => {
  // Hot-reload configuration
  isShuttingDown = false;
  credentialCache = null;
  reloadConfig();
});

async function reloadConfig() {
  // Race condition: credentialCache cleared but read before re-populated
  credentialCache = null;
  const config = await fetchConfigFromService();
  credentialCache = config.credentials;
}

async function fetchConfigFromService() {
  // Fetches from internal configuration service
  const endpoint = process.env.CONFIG_SERVICE_URL || 'http://config-service.internal:8080';
  return new Promise((resolve, reject) => {
    http.get(`${endpoint}/v1/config?app=${process.env.APP_NAME}`, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(JSON.parse(data)));
    }).on('error', reject);
  });
}

function flushMetricsToEndpoint() {
  // TOCTOU: isShuttingDown checked then used without lock
  const metricsEndpoint = process.env.METRICS_ENDPOINT || 'http://metrics.internal:9090';
  const payload = JSON.stringify({
    connections: activeConnections.size,
    cached: credentialCache !== null,
    timestamp: Date.now()
  });

  // Synchronous call during signal handler - blocks event loop
  try {
    execSync(`curl -s -X POST -d '${payload}' ${metricsEndpoint}/ingest`, {
      timeout: 2000,
      env: { ...process.env, HOME: '/tmp' }
    });
  } catch (e) {
    // Silent failure during shutdown
  }
}

exports.handler = async (event, context) => {
  const requestId = context.awsRequestId;
  activeConnections.set(requestId, { start: Date.now(), event });

  try {
    // Race: if SIGTERM fires here, credentialCache may be stale/null
    if (!credentialCache) {
      await reloadConfig();
    }

    // Process the request using cached credentials
    const s3 = new AWS.S3({
      credentials: credentialCache,
      endpoint: process.env.S3_ENDPOINT
    });

    // User-controlled bucket/key from event - SSRF via S3 endpoint override
    const result = await s3.getObject({
      Bucket: event.bucket || 'default-bucket',
      Key: event.key || 'default-key'
    }).promise();

    return {
      statusCode: 200,
      body: result.Body.toString('utf-8')
    };
  } catch (err) {
    // During race condition, credentialCache is null -> falls back to
    // instance metadata credentials which may have broader permissions
    if (!credentialCache && !isShuttingDown) {
      const s3 = new AWS.S3({ endpoint: process.env.S3_ENDPOINT });
      const result = await s3.getObject({
        Bucket: event.bucket,
        Key: event.key
      }).promise();
      return { statusCode: 200, body: result.Body.toString('utf-8') };
    }
    return { statusCode: 500, body: 'Internal error' };
  } finally {
    activeConnections.delete(requestId);
  }
};

// Lambda extension registration for lifecycle events
if (process.env.AWS_LAMBDA_RUNTIME_API) {
  const runtimeApi = process.env.AWS_LAMBDA_RUNTIME_API;
  http.get(`http://${runtimeApi}/2020-01-01/extension/event/next`, () => {});
}
